export class MockHackerOneClient implements ApiClient {
  private readonly programs: Program[];
  private readonly reports: Report[];
  private callCount = 0;

  constructor(opts: { programs?: Program[]; reports?: Report[] } = {}) {
    this.programs = opts.programs ?? FIXTURE_PROGRAMS;
    this.reports = opts.reports ?? FIXTURE_REPORTS;
  }

  async listPrograms(): Promise<Program[]> {
    this.callCount++;
    return this.programs;
  }

  async getProgram(handle: string): Promise<Program> {
    this.callCount++;
    const p = this.programs.find((x) => x.handle === handle);
    if (!p) throw new Error(`@metaharness/hackerone: mock program "${handle}" not found`);
    return p;
  }

  async listReports(
    programHandle: string,
    opts: { state?: string; limit?: number } = {},
  ): Promise<Report[]> {
    this.callCount++;
    let r = this.reports.filter((x) => x.programHandle === programHandle);
    if (opts.state) r = r.filter((x) => x.state === opts.state);
    if (opts.limit) r = r.slice(0, opts.limit);
    return r;
  }

  async getReport(reportId: string): Promise<Report> {
    this.callCount++;
    const r = this.reports.find((x) => x.id === reportId);
    if (!r) throw new Error(`@metaharness/hackerone: mock report "${reportId}" not found`);
    return r;
  }

  async ping(): Promise<{ ok: boolean; mock: boolean; rateLimitRemaining: number }> {
    this.callCount++;
    return { ok: true, mock: true, rateLimitRemaining: Number.POSITIVE_INFINITY };
  }

  /** Test-only: read internal call counter. */
  get calls(): number {
    return this.callCount;
  }
}

function mockScope(
  identifier: string,
  assetType: string,
  maxSeverity: Severity | undefined,
  eligibleForBounty: boolean,
): ScopeItem {
  return {
    identifier,
    assetType,
    maxSeverity,
    eligibleForBounty,
  };
}

/** Exposed for tests that want to seed a specific fixture set. */
export const MOCK_FIXTURES = Object.freeze({
  programs: FIXTURE_PROGRAMS,
  reports: FIXTURE_REPORTS,
});

// Tiny in-memory LRU cache for read-only API responses.
//
// Why: batch workflows (`triage-batch`, repeated `assets` calls in a
// recon pipeline, multi-handle scope sweeps) re-fetch the same program
// dozens of times. The HackerOne API doesn't penalize that, but it
// burns tokens off our rate-limit bucket and adds round-trip latency
// the operator can feel.
//
// Why not memoize globally: a long-running process polling distinct
// programs would grow unbounded. LRU + TTL caps both memory + staleness.
//
// SAFETY:
//   - Cache stays per-process. Never written to disk.
//   - No credential, no session cookie, no API key reaches the cache key.
//   - TTL defaults to 60s — short enough that scope changes during a
//     batch run get picked up on the next outer invocation.

export interface LruOptions {
  /** Max distinct keys to retain. Evicted least-recently-used. */
  maxKeys?: number;
  /** Time-to-live in milliseconds. 0 disables TTL (LRU-only). */
  ttlMs?: number;
  /** Override clock (tests). */
  now?: () => number;
}

interface Entry<V> {
  value: V;
  expiresAt: number;
}

/**
 * Simple LRU with TTL. Map iteration order in JS is insertion-order,
 * so we re-insert on access to bump to the MRU end without an extra
 * linked list. set() and get() are amortized O(1).
 */
export class Lru<V> {
  private readonly maxKeys: number;
  private readonly ttlMs: number;
  private readonly store = new Map<string, Entry<V>>();
  private readonly _now: () => number;
  private _hits = 0;
  private _misses = 0;

  constructor(opts: LruOptions = {}) {
    this.maxKeys = opts.maxKeys ?? 128;
    this.ttlMs = opts.ttlMs ?? 60_000;
    this._now = opts.now ?? Date.now;
  }

  get(key: string): V | undefined {
    const entry = this.store.get(key);
    if (!entry) {
      this._misses += 1;
      return undefined;
    }
    if (this.ttlMs > 0 && this._now() > entry.expiresAt) {
      this.store.delete(key);
      this._misses += 1;
      return undefined;
    }
    // Bump to MRU
    this.store.delete(key);
    this.store.set(key, entry);
    this._hits += 1;
    return entry.value;
  }

  set(key: string, value: V): void {
    if (this.store.has(key)) this.store.delete(key);
    this.store.set(key, {
      value,
      expiresAt: this.ttlMs > 0 ? this._now() + this.ttlMs : Number.POSITIVE_INFINITY,
    });
    if (this.store.size > this.maxKeys) {
      const lru = this.store.keys().next().value;
      if (lru !== undefined) this.store.delete(lru);
    }
  }

  /** Test/diagnostics: hit/miss counters since construction. */
  stats(): { hits: number; misses: number; size: number } {
    return { hits: this._hits, misses: this._misses, size: this.store.size };
  }

  clear(): void {
    this.store.clear();
    this._hits = 0;
    this._misses = 0;
  }
}

/**
 * Async memoization: wrap a fetcher so repeat calls with the same key
 * dedupe + serve from cache. Concurrent calls for the same key share
 * a single in-flight Promise (prevents thundering herd).
 */
export function asyncMemo<K extends string, V>(
  cache: Lru<V>,
  fetcher: (key: K) => Promise<V>,
): (key: K) => Promise<V> {
  const inflight = new Map<K, Promise<V>>();
  return async (key: K): Promise<V> => {
    const hit = cache.get(key);
    if (hit !== undefined) return hit;
    const pending = inflight.get(key);
    if (pending) return pending;
    const p = (async () => {
      try {
        const v = await fetcher(key);
        cache.set(key, v);
        return v;
      } finally {
        inflight.delete(key);
      }
    })();
    inflight.set(key, p);
    return p;
  };
}

import { describe, it, expect, vi } from 'vitest';
import { Lru, asyncMemo } from '../src/api/cache.js';

describe('Lru', () => {
  it('returns undefined on miss', () => {
    const lru = new Lru<number>();
    expect(lru.get('x')).toBeUndefined();
    expect(lru.stats().misses).toBe(1);
  });

  it('returns set value on hit', () => {
    const lru = new Lru<number>();
    lru.set('x', 42);
    expect(lru.get('x')).toBe(42);
    expect(lru.stats().hits).toBe(1);
  });

  it('evicts least-recently-used', () => {
    const lru = new Lru<number>({ maxKeys: 2 });
    lru.set('a', 1);
    lru.set('b', 2);
    lru.set('c', 3); // evicts a
    expect(lru.get('a')).toBeUndefined();
    expect(lru.get('b')).toBe(2);
    expect(lru.get('c')).toBe(3);
  });

  it('bumps MRU on access — `a` survives later eviction', () => {
    const lru = new Lru<number>({ maxKeys: 2 });
    lru.set('a', 1);
    lru.set('b', 2);
    expect(lru.get('a')).toBe(1); // bumps a to MRU
    lru.set('c', 3); // now b is LRU, evicted
    expect(lru.get('b')).toBeUndefined();
    expect(lru.get('a')).toBe(1);
  });

  it('respects TTL', () => {
    let now = 1_000_000;
    const lru = new Lru<number>({ ttlMs: 100, now: () => now });
    lru.set('x', 1);
    now += 50;
    expect(lru.get('x')).toBe(1);
    now += 100; // total 150ms — past 100ms TTL
    expect(lru.get('x')).toBeUndefined();
  });

  it('ttlMs=0 disables TTL (LRU-only)', () => {
    let now = 1;
    const lru = new Lru<number>({ ttlMs: 0, now: () => now });
    lru.set('x', 1);
    now += 999_999_999;
    expect(lru.get('x')).toBe(1);
  });

  it('clear resets stats + store', () => {
    const lru = new Lru<number>();
    lru.set('x', 1);
    lru.get('x');
    lru.clear();
    expect(lru.stats().size).toBe(0);
    expect(lru.stats().hits).toBe(0);
    expect(lru.get('x')).toBeUndefined();
  });
});

describe('asyncMemo', () => {
  it('caches by key — second call hits cache, fetcher not re-invoked', async () => {
    const fetcher = vi.fn(async (k: string) => `v:${k}`);
    const cache = new Lru<string>();
    const wrapped = asyncMemo<string, string>(cache, fetcher);
    expect(await wrapped('a')).toBe('v:a');
    expect(await wrapped('a')).toBe('v:a');
    expect(fetcher).toHaveBeenCalledTimes(1);
  });

  it('concurrent calls for the same key share a single in-flight promise', async () => {
    const fetcher = vi.fn(async (k: string) => {
      await new Promise((r) => setTimeout(r, 20));
      return `v:${k}`;
    });
    const cache = new Lru<string>();
    const wrapped = asyncMemo<string, string>(cache, fetcher);
    const [a, b] = await Promise.all([wrapped('x'), wrapped('x')]);
    expect(a).toBe('v:x');
    expect(b).toBe('v:x');
    expect(fetcher).toHaveBeenCalledTimes(1); // thundering-herd prevented
  });

  it('different keys are fetched independently', async () => {
    const fetcher = vi.fn(async (k: string) => `v:${k}`);
    const cache = new Lru<string>();
    const wrapped = asyncMemo<string, string>(cache, fetcher);
    await wrapped('a');
    await wrapped('b');
    expect(fetcher).toHaveBeenCalledTimes(2);
  });

  it('a failed fetch is NOT cached — next call retries', async () => {
    let calls = 0;
    const fetcher = vi.fn(async (k: string) => {
      calls++;
      if (calls === 1) throw new Error('boom');
      return `v:${k}`;
    });
    const cache = new Lru<string>();
    const wrapped = asyncMemo<string, string>(cache, fetcher);
    await expect(wrapped('a')).rejects.toThrow('boom');
    expect(await wrapped('a')).toBe('v:a');
    expect(fetcher).toHaveBeenCalledTimes(2);
  });
});

// Format a Finding as a HackerOne-style submission markdown report.
//
// Output template follows the de-facto bug-bounty report structure:
//   - Title
//   - Summary
//   - Steps to Reproduce
//   - Impact
//   - CWE / OWASP classification
//   - CVSS vector + score
//   - Supporting Materials (optional)
//   - Researcher Recommendation
//
// All sections are renderable from a Finding without external data.
// PII redaction is the caller's responsibility (apply src/safety.ts:redactPii
// to user-controlled fields BEFORE passing them in if they came from logs).

import type { Finding, Severity } from '../types.js';

export interface ReportFormatOptions {
  includeClassificationSection?: boolean;
  /** Override the researcher-attribution line in the footer. */
  researcher?: string;
}

export function formatFinding(finding: Finding, opts: ReportFormatOptions = {}): string {
  const lines: string[] = [];
  lines.push(`# ${finding.title}`);
  lines.push('');

  lines.push('## Summary');
  lines.push(finding.description || '_(no description)_');
  lines.push('');

  if (finding.reproduction) {
    lines.push('## Steps to Reproduce');
    lines.push(finding.reproduction);
    lines.push('');
  }

  lines.push('## Impact');
  lines.push(impactNarrative(finding.severity, finding.cvssScore));
  lines.push('');

  if (opts.includeClassificationSection !== false) {
    lines.push('## Classification');
    lines.push(`- **Asset:** \`${finding.asset}\``);
    if (finding.cwe) lines.push(`- **CWE:** ${finding.cwe}`);
    if (finding.owasp) lines.push(`- **OWASP Top-10 (2021):** ${finding.owasp}`);
    if (finding.severity) lines.push(`- **Severity:** ${finding.severity}`);
    if (finding.cvssScore !== undefined) lines.push(`- **CVSS Base Score:** ${finding.cvssScore}`);
    if (finding.cvssVector) lines.push(`- **CVSS Vector:** \`${finding.cvssVector}\``);
    lines.push('');
  }

  lines.push('## Researcher Recommendation');
  lines.push(recommendationFor(finding));
  lines.push('');

  lines.push('---');
  lines.push(`_Generated by @metaharness/hackerone v0.1.0${opts.researcher ? ` for ${opts.researcher}` : ''}_`);

  return lines.join('\n');
}

function impactNarrative(severity: Severity | undefined, score: number | undefined): string {
  const sev = severity ?? 'medium';
  const scoreStr = score !== undefined ? ` (CVSS base ${score})` : '';
  switch (sev) {
    case 'critical':
      return `**Critical${scoreStr}** — full compromise of confidentiality, integrity, or availability. Attacker can gain admin/root, exfiltrate sensitive data, or take the service offline at scale.`;
    case 'high':
      return `**High${scoreStr}** — significant compromise. Attacker can escalate privileges, access other users' data, or trigger material business impact.`;
    case 'medium':
      return `**Medium${scoreStr}** — partial compromise. Some data exposure, limited unauthorized access, or moderate availability impact.`;
    case 'low':
      return `**Low${scoreStr}** — minor compromise or hardening gap. Limited material impact in most scenarios.`;
    case 'none':
      return `**Informational${scoreStr}** — no direct exploitability; useful as defense-in-depth context.`;
    default:
      return `**Impact${scoreStr}** — see description.`;
  }
}

function recommendationFor(finding: Finding): string {
  const sev = finding.severity ?? 'medium';
  const urgency = sev === 'critical' || sev === 'high' ? 'immediately' : 'in the next sprint';
  const cweHint = finding.cwe ? ` ${finding.cwe}-class` : '';
  return (
    `Address this${cweHint} finding ${urgency}. Reproduce in a staging environment first, ` +
    `then apply the standard mitigation for the CWE (see CWE database). Validate the fix by ` +
    `re-running the repro steps and confirming the unsafe behavior no longer occurs.`
  );
}

// Named error classes for API failures.
//
// Replaces generic `throw new Error("...")` so:
//   1. CLI can show the right hint (rate limit vs auth vs missing)
//   2. Callers can branch on instanceof (downstream tooling)
//   3. Error messages never echo the auth header or session cookie
//
// All error messages are constructed inside this module so we control
// what reaches stdout/stderr. Don't let an `unknown` payload (response
// body, header, etc.) be concatenated into a message at the throw site.

export class HackerOneApiError extends Error {
  readonly hint?: string;
  constructor(message: string, hint?: string) {
    super(message);
    this.name = 'HackerOneApiError';
    if (hint !== undefined) this.hint = hint;
  }
  toString(): string {
    return this.hint ? `${this.message}\n  hint: ${this.hint}` : this.message;
  }
}

/** 401 / auth-failed. Hint depends on transport. */
export class GraphQLAuthError extends HackerOneApiError {
  constructor(statusText: string) {
    super(
      `GraphQL endpoint refused auth (HTTP 401 ${statusText})`,
      'GraphQL needs X-Auth-Token (not Basic). For `me` / private programs ' +
        'also set HACKERONE_SESSION_COOKIE — token alone authenticates only public queries.',
    );
    this.name = 'GraphQLAuthError';
  }
}

/** GraphQL returned an `errors:[…]` block. */
export class GraphQLQueryError extends HackerOneApiError {
  readonly errors: ReadonlyArray<{ message: string }>;
  constructor(errors: ReadonlyArray<{ message: string }>) {
    super(
      'GraphQL query failed: ' + errors.map((e) => e.message).join('; '),
      'If the message mentions "undefinedField", the internal schema may ' +
        'have changed; pin to a known query in src/api/graphql-client.ts.',
    );
    this.name = 'GraphQLQueryError';
    this.errors = errors;
  }
}

export class RestAuthError extends HackerOneApiError {
  constructor(statusText: string) {
    super(
      `REST endpoint refused auth (HTTP 401 ${statusText})`,
      'HackerOne Basic auth uses <api-identifier>:<api-token>. Set ' +
        'HACKERONE_API_USERNAME to the API identifier shown at ' +
        'hackerone.com/users/<you>/api_tokens — NOT your profile username.',
    );
    this.name = 'RestAuthError';
  }
}

export class NotFoundError extends HackerOneApiError {
  constructor(what: string) {
    super(`${what} not found`);
    this.name = 'NotFoundError';
  }
}

export class RateLimitExceededError extends HackerOneApiError {
  constructor() {
    super(
      'Rate limit exceeded (token bucket empty — local-side cap)',
      'The HackerOne API has its own server-side limits too. Wait 60s ' +
        'or back off your batch size.',
    );
    this.name = 'RateLimitExceededError';
  }
}

export class TimeoutError extends HackerOneApiError {
  constructor(operation: string, ms: number) {
    super(`${operation} timed out after ${ms}ms`);
    this.name = 'TimeoutError';
  }
}

