// Extract a flat list of asset identifiers from a Program — the
// stdin-friendly form recon tools (Subfinder, Amass, Nuclei, etc.) expect.
//
// Each tool reads newline-delimited identifiers from stdin/-dL/-df. The
// asset-list extractor lets the harness drop straight into:
//
//   npx hackerone assets <handle> | subfinder -dL -
//   npx hackerone assets <handle> --type URL,DOMAIN | amass enum -df -
//   npx hackerone scope <handle> --format lines | nuclei -l -
//
// This module is pure (no I/O) — the CLI/MCP layer wraps it.

import type { Program, ScopeItem } from '../types.js';

export interface AssetListOptions {
  /** Filter to specific asset types (URL, DOMAIN, API, IOS_APP_STORE, …). */
  assetTypes?: string[];
  /**
   * Whether to include out-of-scope assets in the output. DEFAULT: false —
   * piping out-of-scope identifiers into a recon tool would test forbidden
   * targets, a policy violation. Caller MUST opt in explicitly.
   */
  includeOutOfScope?: boolean;
  /** Whether to expand "*.example.com" wildcards to a normalized form. */
  expandWildcards?: boolean;
  /**
   * Whether to deduplicate (case-insensitive). DEFAULT: true. Some recon
   * tools dedupe themselves but emitting clean lists is the polite thing.
   */
  dedupe?: boolean;
}

/**
 * Extract a flat, deduplicated list of in-scope asset identifiers.
 *
 * SAFETY: by default this returns ONLY in-scope assets. The caller must
 * pass `includeOutOfScope: true` to opt into out-of-scope identifiers,
 * and even then a banner string is the recommended emit path
 * (`formatAssetListWithBanner`) so the operator sees them flagged.
 */
export function extractAssets(program: Program, opts: AssetListOptions = {}): string[] {
  const dedupe = opts.dedupe !== false;
  const sources: ScopeItem[] = [];
  sources.push(...program.scope);
  if (opts.includeOutOfScope) sources.push(...program.outOfScope);

  let items = sources;
  if (opts.assetTypes && opts.assetTypes.length > 0) {
    const allowed = new Set(opts.assetTypes.map((t) => t.toUpperCase()));
    items = items.filter((s) => allowed.has(s.assetType?.toUpperCase()));
  }

  let ids = items.map((s) => normalize(s.identifier, opts));
  if (dedupe) {
    const seen = new Set<string>();
    ids = ids.filter((id) => {
      const k = id.toLowerCase();
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    });
  }
  return ids;
}

/**
 * Like extractAssets() but renders a leading banner comment block listing
 * any out-of-scope identifiers (when includeOutOfScope is true) so a human
 * piping into a recon tool sees them clearly flagged.
 *
 * The format is:
 *
 *   # @metaharness/hackerone — program=<handle> in-scope=N out-of-scope=M
 *   # OUT-OF-SCOPE (do not test):
 *   #   marketing.example.com
 *   <in-scope identifiers, one per line>
 *
 * Subfinder/Amass/Nuclei all ignore lines starting with `#`, so the
 * banner is a no-op for them but informative for humans.
 */
export function formatAssetListWithBanner(program: Program, opts: AssetListOptions = {}): string {
  const inScope = extractAssets(program, { ...opts, includeOutOfScope: false });
  const outOfScope = opts.includeOutOfScope
    ? extractAssets(program, { ...opts, includeOutOfScope: true }).filter(
        (id) => !inScope.includes(id),
      )
    : [];
  const lines: string[] = [];
  lines.push(
    `# @metaharness/hackerone — program=${program.handle} in-scope=${inScope.length} out-of-scope=${outOfScope.length}`,
  );
  if (outOfScope.length > 0) {
    lines.push('# OUT-OF-SCOPE (do not test):');
    for (const id of outOfScope) lines.push(`#   ${id}`);
  }
  lines.push(...inScope);
  return lines.join('\n');
}

/**
 * Normalize an asset identifier for piping. Strips protocol + trailing
 * slash. Optionally expands `*.foo` → `foo` for tools that don't
 * understand the wildcard (e.g., Subfinder treats `foo` as the apex and
 * enumerates subdomains itself).
 */
function normalize(raw: string, opts: AssetListOptions): string {
  let s = raw.trim();
  s = s.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
  if (opts.expandWildcards && s.startsWith('*.')) {
    s = s.slice(2);
  }
  return s;
}

// Researcher-side recon orchestrator.
//
// Wraps scope-analysis + cwe-map + report-format into a single
// "where to look, what to look for, how to write it up" workflow.
//
// Inputs: a Program (from the API or a fixture).
// Outputs: ScopeAnalysis + an opening checklist + (optional) a draft
// report skeleton for a hypothetical finding the researcher describes.

import type { Program } from '../types.js';
import { analyzeScope } from './scope-analysis.js';
import { classifyDescription } from './cwe-map.js';
import { formatFinding } from './report-format.js';

export interface ReconResult {
  programHandle: string;
  offersBounties: boolean;
  topAssets: Array<{ identifier: string; assetType: string; maxSeverity?: string; weight: number }>;
  forbiddenAssets: string[];
  totalChecksSuggested: number;
  topChecks: string[];
}

/**
 * Build a recon plan for a program — what to test first, what to avoid,
 * what families of bugs to look for.
 *
 * Cheap; runs in microseconds; no I/O.
 */
export function buildReconPlan(program: Program): ReconResult {
  const scope = analyzeScope(program);
  const topAssets = scope.testableAssets.slice(0, 5).map((a) => ({
    identifier: a.identifier,
    assetType: a.assetType,
    maxSeverity: a.maxSeverity,
    weight: weightOf(a.maxSeverity),
  }));
  const allChecks = new Set<string>();
  for (const c of scope.suggestedChecks) {
    for (const x of c.checks) allChecks.add(x);
  }
  const result: ReconResult = {
    programHandle: program.handle,
    offersBounties: program.offersBounties,
    topAssets,
    forbiddenAssets: scope.forbidden.map((f) => f.identifier),
    totalChecksSuggested: allChecks.size,
    topChecks: [...allChecks].slice(0, 8),
  };
  return result;
}

function weightOf(sev: string | undefined): number {
  switch (sev) {
    case 'critical': return 4;
    case 'high': return 3;
    case 'medium': return 2;
    case 'low': return 1;
    default: return 2; // assume medium when unknown
  }
}

export { analyzeScope, classifyDescription, formatFinding };

// HackerOne API client — read-only, rate-limited, mock-by-default.
//
// Wraps the HackerOne REST/JSON API surface at https://api.hackerone.com.
// Only the endpoints the harness actually needs are exposed here; we add
// more as new triage/research features land.
//
// Safety posture:
//   - All methods are READ-ONLY in v0.1. Writes (state changes, comments,
//     bounties) are NOT implemented and refuse at the API boundary.
//   - RateLimiter caps calls per minute (HARD_SAFE_DEFAULTS.maxApiCallsPerMin).
//   - Every fetch() uses a 30s timeout and AbortController.
//   - Errors are wrapped to never expose the Authorization header in
//     diagnostics.

import type { Program, Report, ScopeItem } from '../types.js';
import {
  HARD_SAFE_DEFAULTS,
  RateLimiter,
  SafetyViolationError,
  validateProgramHandle,
} from '../safety.js';
import { toBasicAuthHeader } from './key-source.js';
import { HackerOneApiError, RateLimitExceededError, RestAuthError } from './errors.js';

const BASE_URL = 'https://api.hackerone.com/v1';
const DEFAULT_TIMEOUT_MS = 30_000;

export interface HackerOneClientOptions {
  apiKey: string;
  baseUrl?: string;
  timeoutMs?: number;
  maxCallsPerMin?: number;
  /** Override fetch (for tests). */
  fetchImpl?: typeof fetch;
}

export interface ApiClient {
  listPrograms(): Promise<Program[]>;
  getProgram(handle: string): Promise<Program>;
  listReports(programHandle: string, opts?: { state?: string; limit?: number }): Promise<Report[]>;
  getReport(reportId: string): Promise<Report>;
  /** Health/diagnostic — never makes real calls in mock mode. */
  ping(): Promise<{ ok: boolean; mock: boolean; rateLimitRemaining: number }>;
}

export class HackerOneClient implements ApiClient {
  private readonly authHeader: string;
  private readonly baseUrl: string;
  private readonly timeoutMs: number;
  private readonly rateLimiter: RateLimiter;
  private readonly fetchImpl: typeof fetch;

  constructor(opts: HackerOneClientOptions) {
    if (!opts.apiKey) {
      throw new SafetyViolationError(
        '@metaharness/hackerone: HackerOneClient requires apiKey — use MockHackerOneClient when no key is available',
      );
    }
    this.authHeader = toBasicAuthHeader(opts.apiKey);
    this.baseUrl = opts.baseUrl ?? BASE_URL;
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.rateLimiter = new RateLimiter(opts.maxCallsPerMin ?? HARD_SAFE_DEFAULTS.maxApiCallsPerMin);
    this.fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  }

  async listPrograms(): Promise<Program[]> {
    const body = await this.get<{ data: H1Program[] }>('/me/programs');
    return body.data.map(parseProgram);
  }

  async getProgram(handle: string): Promise<Program> {
    validateProgramHandle(handle);
    const body = await this.get<{ data: H1Program }>(`/programs/${encodeURIComponent(handle)}`);
    return parseProgram(body.data);
  }

  async listReports(
    programHandle: string,
    opts: { state?: string; limit?: number } = {},
  ): Promise<Report[]> {
    validateProgramHandle(programHandle);
    const params = new URLSearchParams();
    params.set('filter[program][]', programHandle);
    if (opts.state) params.set('filter[state][]', opts.state);
    if (opts.limit) params.set('page[size]', String(Math.min(100, Math.max(1, opts.limit))));
    const body = await this.get<{ data: H1Report[] }>(`/reports?${params}`);
    return body.data.map(parseReport);
  }

  async getReport(reportId: string): Promise<Report> {
    if (!/^[0-9]+$/.test(reportId)) {
      throw new SafetyViolationError(
        `@metaharness/hackerone: invalid report id "${reportId}" — must be numeric`,
      );
    }
    const body = await this.get<{ data: H1Report }>(`/reports/${reportId}`);
    return parseReport(body.data);
  }

  async ping(): Promise<{ ok: boolean; mock: boolean; rateLimitRemaining: number }> {
    try {
      await this.get<unknown>('/me');
      return { ok: true, mock: false, rateLimitRemaining: this.rateLimiter.remaining };
    } catch {
      return { ok: false, mock: false, rateLimitRemaining: this.rateLimiter.remaining };
    }
  }

  // ────────────────────────────────────────────────────────────────────
  // Internal: rate-limited fetch with timeout.
  // ────────────────────────────────────────────────────────────────────
  private async get<T>(path: string): Promise<T> {
    if (!this.rateLimiter.tryConsume()) {
      throw new RateLimitExceededError();
    }
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), this.timeoutMs);
    let resp: Response;
    try {
      resp = await this.fetchImpl(this.baseUrl + path, {
        method: 'GET',
        headers: {
          Accept: 'application/json',
          Authorization: [REDACTED],
          'User-Agent': '@metaharness/hackerone (v0.1.0)',
        },
        signal: ctrl.signal,
      });
    } finally {
      clearTimeout(timer);
    }
    if (!resp.ok) {
      if (resp.status === 401) throw new RestAuthError(resp.statusText);
      throw new HackerOneApiError(`GET ${path} → HTTP ${resp.status} ${resp.statusText}`);
    }
    return (await resp.json()) as T;
  }
}

// ──────────────────────────────────────────────────────────────────────
// HackerOne JSON-API shape (the wire format, kept internal so consumers
// only see the narrowed shapes from types.ts).
// ──────────────────────────────────────────────────────────────────────

interface H1Program {
  id: string;
  type: string;
  attributes: {
    handle: string;
    name?: string;
    offers_bounties?: boolean;
    updated_at?: string;
  };
  relationships?: {
    structured_scopes?: { data: Array<{ attributes: H1ScopeAttrs }> };
  };
}

interface H1ScopeAttrs {
  asset_identifier: string;
  asset_type: string;
  eligible_for_bounty?: boolean;
  max_severity?: string;
  instruction?: string;
  eligible_for_submission?: boolean;
}

interface H1Report {
  id: string;
  attributes: {
    title: string;
    state: string;
    vulnerability_information?: string;
    severity?: { rating?: string; score?: number };
    cve_ids?: string[];
    created_at?: string;
    bounty_awarded_amount?: number;
  };
  relationships?: {
    program?: { data: { attributes: { handle: string } } };
    structured_scope?: { data: { attributes: { asset_identifier: string } } };
    weakness?: { data: { attributes: { external_id?: string; name?: string } } };
  };
}

function parseProgram(p: H1Program): Program {
  const scopes = p.relationships?.structured_scopes?.data ?? [];
  const inScope = scopes
    .filter((s) => s.attributes.eligible_for_submission !== false)
    .map(parseScopeItem);
  const outOfScope = scopes
    .filter((s) => s.attributes.eligible_for_submission === false)
    .map(parseScopeItem);
  return {
    handle: p.attributes.handle,
    name: p.attributes.name ?? p.attributes.handle,
    scope: inScope,
    outOfScope,
    offersBounties: p.attributes.offers_bounties ?? false,
    updatedAt: p.attributes.updated_at,
  };
}

function parseScopeItem(s: { attributes: H1ScopeAttrs }): ScopeItem {
  return {
    identifier: s.attributes.asset_identifier,
    assetType: s.attributes.asset_type,
    eligibleForBounty: s.attributes.eligible_for_bounty,
    maxSeverity: s.attributes.max_severity?.toLowerCase() as ScopeItem['maxSeverity'],
    instructions: s.attributes.instruction,
  };
}

function parseReport(r: H1Report): Report {
  const programHandle = r.relationships?.program?.data?.attributes?.handle ?? 'unknown';
  const asset = r.relationships?.structured_scope?.data?.attributes?.asset_identifier ?? 'unknown';
  const cwe = r.relationships?.weakness?.data?.attributes?.external_id;
  const severityRaw = r.attributes.severity?.rating?.toLowerCase();
  const severity = (
    ['none', 'low', 'medium', 'high', 'critical'].includes(severityRaw ?? '')
      ? severityRaw
      : undefined
  ) as Report['finding']['severity'];

  return {
    id: r.id,
    programHandle,
    state: r.attributes.state as Report['state'],
    submittedAt: r.attributes.created_at,
    bountyAmount: r.attributes.bounty_awarded_amount,
    finding: {
      id: r.id,
      title: r.attributes.title,
      description: r.attributes.vulnerability_information ?? '',
      cvssScore: r.attributes.severity?.score,
      severity,
      cwe,
      asset,
      createdAt: r.attributes.created_at,
    },
  };
}

// Bridge: convert a @metaharness/hackerone Finding → an engineering
// ticket POST body for Jira or GitHub Issues.
//
// This closes the defender-side "fix" workflow: an analyst triages a
// HackerOne report with this harness, then pipes the finding straight
// into their internal tracker:
//
//   npx hackerone export-issue finding.json --kind github --repo owner/name \
//     | curl -X POST https://api.github.com/repos/owner/name/issues \
//         -H "Authorization: Bearer $GITHUB_TOKEN" \
//         -H "Accept: application/vnd.github+json" \
//         -d @-
//
//   npx hackerone export-issue finding.json --kind jira --project SEC \
//     | curl -X POST https://your-org.atlassian.net/rest/api/3/issue \
//         -H "Authorization: Basic $JIRA_TOKEN" \
//         -H "Content-Type: application/json" \
//         -d @-
//
// SAFETY (load-bearing — DO NOT WEAKEN):
//   - Pure transform. No network calls. No tokens read.
//   - PII redaction applied to the description before emit
//     (redactPii from safety.ts) — the engineering tracker may have
//     wider access than the security team.
//   - No automation of the POST itself. The operator pipes to curl;
//     this stays well inside HackerOne's "automation does
//     discovery→validate→draft→scope-check, a human owns each
//     submission" line, applied to engineering-ticket creation.
//   - Title prefix `[H1#<id>]` is hard-coded so engineering can search
//     and dedupe; rejecting an unsigned prefix is a future ticket-side
//     concern.

import type { Finding, Severity } from '../types.js';
import { redactPii } from '../safety.js';

export type IssueKind = 'jira' | 'github';

/** GitHub Issues POST body shape (subset we populate). */
export interface GithubIssueBody {
  title: string;
  body: string;
  labels: string[];
  assignees?: string[];
}

/** Jira issue create body (subset we populate). */
export interface JiraIssueBody {
  fields: {
    project: { key: string };
    summary: string;
    /** Atlassian Document Format (plain doc with paragraphs). */
    description: {
      type: 'doc';
      version: 1;
      content: Array<{
        type: 'paragraph';
        content: Array<{ type: 'text'; text: string }>;
      }>;
    };
    issuetype: { name: string };
    priority?: { name: string };
    labels?: string[];
  };
}

export interface IssueBridgeOptions {
  /** Jira: project key. e.g., "SEC", "PLATFORM" */
  project?: string;
  /** GitHub: "owner/name" (informational only; goes in the title prefix). */
  repo?: string;
  /** Override the default issue-type / labels. */
  issueType?: string;
  /** Additional labels to append. */
  labels?: string[];
  /** GitHub-only: assignees. */
  assignees?: string[];
  /** HackerOne report id, prepended to the title for searchability. */
  hackeroneReportId?: string;
  /** Skip the PII redaction step (operator override; off by default). */
  skipPiiRedaction?: boolean;
}

/** Severity → Jira priority name. Sane defaults; orgs can re-map their own. */
const JIRA_PRIORITY: Record<Severity, string> = {
  critical: 'Highest',
  high: 'High',
  medium: 'Medium',
  low: 'Low',
  none: 'Lowest',
};

/** Severity → GitHub label suffix. */
const GH_SEV_LABEL: Record<Severity, string> = {
  critical: 'severity/critical',
  high: 'severity/high',
  medium: 'severity/medium',
  low: 'severity/low',
  none: 'severity/info',
};

/** Build the title: "[H1#1234] Reflected XSS in /search?q=" */
function buildTitle(finding: Finding, hackeroneReportId?: string): string {
  const prefix = hackeroneReportId ? `[H1#${hackeroneReportId}] ` : '[H1] ';
  return prefix + finding.title;
}

/** Markdown body shared between Jira-plain and GitHub. */
function buildMarkdown(finding: Finding, opts: IssueBridgeOptions): string {
  const sev = finding.severity ?? 'medium';
  const redact = opts.skipPiiRedaction ? (s: string) => s : redactPii;
  const lines: string[] = [];
  lines.push('## Summary');
  lines.push(redact(finding.description || '_(no description)_'));
  lines.push('');
  if (finding.reproduction) {
    lines.push('## Steps to Reproduce');
    lines.push(redact(finding.reproduction));
    lines.push('');
  }
  lines.push('## Classification');
  lines.push(`- **Asset:** \`${finding.asset}\``);
  lines.push(`- **Severity:** ${sev}` + (finding.cvssScore !== undefined ? ` (CVSS ${finding.cvssScore})` : ''));
  if (finding.cwe) lines.push(`- **CWE:** ${finding.cwe}`);
  if (finding.owasp) lines.push(`- **OWASP Top-10 (2021):** ${finding.owasp}`);
  if (finding.cvssVector) lines.push(`- **CVSS Vector:** \`${finding.cvssVector}\``);
  lines.push('');
  lines.push('---');
  lines.push(`_Filed via @metaharness/hackerone v0.1.0 — defender triage → engineering sync._`);
  if (opts.hackeroneReportId) lines.push(`_Source: HackerOne report ${opts.hackeroneReportId}_`);
  return lines.join('\n');
}

/** Build a GitHub Issues POST body from a finding. */
export function toGithubIssue(finding: Finding, opts: IssueBridgeOptions = {}): GithubIssueBody {
  const sev = finding.severity ?? 'medium';
  const labels = new Set<string>([
    'security',
    GH_SEV_LABEL[sev],
    ...(finding.cwe ? [`cwe/${finding.cwe.toLowerCase()}`] : []),
    ...(opts.labels ?? []),
  ]);
  const out: GithubIssueBody = {
    title: buildTitle(finding, opts.hackeroneReportId),
    body: buildMarkdown(finding, opts),
    labels: [...labels],
  };
  if (opts.assignees && opts.assignees.length > 0) out.assignees = opts.assignees;
  return out;
}

/** Build a Jira issue-create POST body from a finding. */
export function toJiraIssue(finding: Finding, opts: IssueBridgeOptions = {}): JiraIssueBody {
  if (!opts.project) {
    throw new Error('@metaharness/hackerone: --project <KEY> is required for Jira (e.g., SEC)');
  }
  const sev = finding.severity ?? 'medium';
  const labels: string[] = [
    'security',
    `severity-${sev}`,
    ...(finding.cwe ? [finding.cwe.toLowerCase()] : []),
    ...(opts.labels ?? []),
  ];
  const md = buildMarkdown(finding, opts);
  // Render markdown as ADF — minimal: each newline-separated paragraph
  // becomes a paragraph block. Jira's full ADF supports headings/lists
  // but a flat paragraph block survives every Jira instance + add-on.
  const paragraphs = md
    .split(/\n\n+/)
    .map((p) => p.trim())
    .filter(Boolean)
    .map((text) => ({
      type: 'paragraph' as const,
      content: [{ type: 'text' as const, text }],
    }));

  return {
    fields: {
      project: { key: opts.project },
      summary: buildTitle(finding, opts.hackeroneReportId),
      description: {
        type: 'doc',
        version: 1,
        content: paragraphs,
      },
      issuetype: { name: opts.issueType ?? 'Bug' },
      priority: { name: JIRA_PRIORITY[sev] },
      labels,
    },
  };
}

/** Dispatch: pick the right transform by kind. */
export function toIssue(kind: IssueKind, finding: Finding, opts: IssueBridgeOptions = {}): GithubIssueBody | JiraIssueBody {
  switch (kind) {
    case 'github': return toGithubIssue(finding, opts);
    case 'jira':   return toJiraIssue(finding, opts);
  }
}

// Map free-text vulnerability descriptions → CWE + OWASP Top-10 (2021).
//
// Lightweight keyword classifier — no ML, no external calls. Each rule
// is a (regex → CWE → OWASP) tuple. Multiple rules may fire; the result
// is the highest-confidence (most specific) hit.
//
// This is intentionally narrow: only the ~25 most common bug classes
// are covered. Researchers can append rules per program; defenders can
// use this as a hint, not a verdict (every CWE assignment needs human
// review).

export interface CweRule {
  cwe: string;
  /** OWASP Top-10 (2021) category id, e.g. "A03:2021". */
  owasp?: string;
  /** Display name. */
  name: string;
  /** Regex applied case-insensitively to the description. */
  patterns: RegExp[];
  /** Higher = more specific. Ties resolved by rule order. */
  specificity: number;
}

export const CWE_RULES: CweRule[] = [
  // ── A03:2021 Injection ────────────────────────────────────────────
  { cwe: 'CWE-89',  owasp: 'A03:2021', name: 'SQL Injection',  specificity: 9,
    patterns: [/sql\s*injection/i, /\bsqli\b/i, /union\s+select/i] },
  { cwe: 'CWE-78',  owasp: 'A03:2021', name: 'OS Command Injection', specificity: 9,
    patterns: [/command\s*injection/i, /\brce\b/i, /remote\s+code\s+execution/i, /shell\s*injection/i] },
  { cwe: 'CWE-94',  owasp: 'A03:2021', name: 'Code Injection',  specificity: 8,
    patterns: [/code\s*injection/i, /\beval\b/i, /dynamic\s+code\s+execution/i] },
  { cwe: 'CWE-79',  owasp: 'A03:2021', name: 'Cross-site Scripting', specificity: 9,
    patterns: [/\bxss\b/i, /cross[-\s]*site\s*scripting/i, /reflected\s+xss/i, /stored\s+xss/i] },
  { cwe: 'CWE-90',  owasp: 'A03:2021', name: 'LDAP Injection',  specificity: 8,
    patterns: [/ldap\s*injection/i] },
  { cwe: 'CWE-91',  owasp: 'A03:2021', name: 'XML Injection',   specificity: 8,
    patterns: [/xml\s*injection/i, /xxe\b/i, /xml\s+external\s+entity/i] },
  { cwe: 'CWE-77',  owasp: 'A03:2021', name: 'Command Injection (generic)', specificity: 6,
    patterns: [/argument\s+injection/i] },

  // ── A01:2021 Broken Access Control ────────────────────────────────
  { cwe: 'CWE-639', owasp: 'A01:2021', name: 'IDOR',            specificity: 9,
    patterns: [/\bidor\b/i, /insecure\s+direct\s+object\s+reference/i] },
  { cwe: 'CWE-285', owasp: 'A01:2021', name: 'Authorization Bypass', specificity: 8,
    patterns: [/authorization\s+bypass/i, /broken\s+access\s+control/i, /privilege\s+escalation/i] },
  { cwe: 'CWE-352', owasp: 'A01:2021', name: 'CSRF',            specificity: 9,
    patterns: [/\bcsrf\b/i, /cross[-\s]*site\s*request\s+forgery/i] },
  { cwe: 'CWE-22',  owasp: 'A01:2021', name: 'Path Traversal',  specificity: 9,
    patterns: [/path\s+traversal/i, /directory\s+traversal/i, /\.\.[\\/]/] },

  // ── A07:2021 Identification and Authentication Failures ───────────
  { cwe: 'CWE-287', owasp: 'A07:2021', name: 'Improper Authentication', specificity: 7,
    patterns: [/auth(?:entication)?\s+bypass/i, /broken\s+auth(?:entication)?/i] },
  { cwe: 'CWE-384', owasp: 'A07:2021', name: 'Session Fixation', specificity: 8,
    patterns: [/session\s+fixation/i] },
  { cwe: 'CWE-521', owasp: 'A07:2021', name: 'Weak Password Requirements', specificity: 7,
    patterns: [/weak\s+password/i, /no\s+password\s+complexity/i] },

  // ── A02:2021 Cryptographic Failures ───────────────────────────────
  { cwe: 'CWE-327', owasp: 'A02:2021', name: 'Broken/Risky Crypto', specificity: 8,
    patterns: [/\bmd5\b/i, /\bsha[-_]?1\b/i, /weak\s+cipher/i, /broken\s+crypto/i, /\brc4\b/i] },
  { cwe: 'CWE-319', owasp: 'A02:2021', name: 'Cleartext Transmission', specificity: 8,
    patterns: [/cleartext\s+transmission/i, /unencrypted\s+(?:http|transport)/i, /no\s+tls/i] },

  // ── A05:2021 Security Misconfiguration ────────────────────────────
  { cwe: 'CWE-16',  owasp: 'A05:2021', name: 'Configuration',    specificity: 5,
    patterns: [/misconfiguration/i, /default\s+credentials/i, /exposed\s+config/i] },
  { cwe: 'CWE-200', owasp: 'A04:2021', name: 'Information Exposure', specificity: 7,
    patterns: [/information\s+(?:exposure|disclosure|leak)/i, /sensitive\s+data\s+exposure/i] },

  // ── A04:2021 Insecure Design ─────────────────────────────────────
  { cwe: 'CWE-918', owasp: 'A10:2021', name: 'Server-Side Request Forgery', specificity: 9,
    patterns: [/\bssrf\b/i, /server[-\s]*side\s*request\s*forgery/i] },

  // ── A06:2021 Vulnerable & Outdated Components ─────────────────────
  { cwe: 'CWE-1104', owasp: 'A06:2021', name: 'Outdated Component', specificity: 7,
    patterns: [/outdated\s+(?:library|component)/i, /vulnerable\s+dependency/i, /\bcve-\d{4}-\d+/i] },

  // ── A08:2021 Software and Data Integrity Failures ────────────────
  { cwe: 'CWE-502', owasp: 'A08:2021', name: 'Insecure Deserialization', specificity: 9,
    patterns: [/insecure\s+deserialization/i, /unsafe\s+(?:pickle|yaml|deserialize)/i] },

  // ── A09:2021 Security Logging and Monitoring Failures ────────────
  { cwe: 'CWE-778', owasp: 'A09:2021', name: 'Insufficient Logging', specificity: 6,
    patterns: [/insufficient\s+logging/i, /no\s+audit\s+log/i] },

  // ── Misc ──────────────────────────────────────────────────────────
  { cwe: 'CWE-601', owasp: 'A01:2021', name: 'Open Redirect',   specificity: 8,
    patterns: [/open\s+redirect/i, /unvalidated\s+redirect/i] },
  { cwe: 'CWE-400', name: 'Resource Exhaustion / DoS', specificity: 6,
    patterns: [/denial\s+of\s+service/i, /\bdos\b/i, /resource\s+exhaustion/i] },
  { cwe: 'CWE-732', owasp: 'A01:2021', name: 'Insecure Permissions', specificity: 6,
    patterns: [/insecure\s+permissions/i, /world[-\s]*(?:readable|writable)/i] },
];

export interface CweClassification {
  cwe: string;
  owasp?: string;
  name: string;
  /** [0..1]; combination of rule specificity and number of patterns matched. */
  confidence: number;
  /** Alternative classifications that also matched, ranked. */
  alternatives: Array<{ cwe: string; owasp?: string; name: string; confidence: number }>;
}

/**
 * Classify a free-text description into a (CWE, OWASP, name).
 *
 * Returns null if NO rule fires. The classifier is intentionally
 * conservative — better to return null than to mislabel.
 */
export function classifyDescription(description: string): CweClassification | null {
  const hits: Array<{ rule: CweRule; matchCount: number; score: number }> = [];
  for (const rule of CWE_RULES) {
    let matchCount = 0;
    for (const p of rule.patterns) {
      if (p.test(description)) matchCount++;
    }
    if (matchCount > 0) {
      // Score = specificity + bonus for multiple patterns matched
      const score = rule.specificity + Math.min(2, matchCount - 1);
      hits.push({ rule, matchCount, score });
    }
  }
  if (hits.length === 0) return null;
  hits.sort((a, b) => b.score - a.score);
  const best = hits[0]!;
  const top = best.rule;
  const maxScore = 11; // specificity 9 + 2 matches
  const result: CweClassification = {
    cwe: top.cwe,
    name: top.name,
    confidence: Math.min(1, best.score / maxScore),
    alternatives: hits.slice(1, 4).map((h) => {
      const alt: CweClassification['alternatives'][number] = {
        cwe: h.rule.cwe,
        name: h.rule.name,
        confidence: Math.min(1, h.score / maxScore),
      };
      if (h.rule.owasp !== undefined) alt.owasp = h.rule.owasp;
      return alt;
    }),
  };
  if (top.owasp !== undefined) result.owasp = top.owasp;
  return result;
}

// Resolve HACKERONE_API_KEY from (in priority order):
//   1. process.env.HACKERONE_API_KEY        — preferred path
//   2. .env file (cwd or repo root)         — local dev
//   3. GCP Secret Manager                   — CI / prod
//
// The resolver NEVER logs the resolved key. Diagnostics return only the
// length + first 4 chars + the source bucket. See KeyResolution in types.ts.
//
// This module shells out to `gcloud secrets versions access` rather than
// adding a heavy SDK dep — the @metaharness/* family keeps deps minimal.
// If gcloud isn't installed, GCP source is skipped silently.

import { readFileSync, existsSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import type { KeyResolution } from '../types.js';

const KEY_NAME = 'HACKERONE_API_KEY';
const GCP_PROJECT_ENV = 'GCP_PROJECT';

export interface KeyResolverOptions {
  /** Override cwd for .env lookup (tests). */
  cwd?: string;
  /** Override gcloud binary path (tests). */
  gcloudBin?: string;
  /** Skip GCP lookup entirely. */
  skipGcp?: boolean;
}

/**
 * Try each source in priority order. Returns the resolved key and a
 * KeyResolution describing where it came from. The key string is the
 * caller's responsibility to handle — DO NOT log it, DO NOT store it on
 * disk, DO NOT include it in error messages.
 */
export function resolveApiKey(opts: KeyResolverOptions = {}): {
  key: string | null;
  resolution: KeyResolution;
} {
  // 1. process.env — highest priority
  const fromEnv = process.env[KEY_NAME];
  if (fromEnv && fromEnv.trim()) {
    return {
      key: fromEnv.trim(),
      resolution: diagnose(fromEnv.trim(), 'env'),
    };
  }

  // 2. .env file (cwd, walking up to repo root)
  const fromDotenv = readFromDotenv(opts.cwd ?? process.cwd());
  if (fromDotenv) {
    return {
      key: fromDotenv,
      resolution: diagnose(fromDotenv, 'dotenv'),
    };
  }

  // 3. GCP Secret Manager
  if (!opts.skipGcp) {
    const gcpProject = process.env[GCP_PROJECT_ENV];
    if (gcpProject) {
      const fromGcp = readFromGcp(KEY_NAME, gcpProject, opts.gcloudBin ?? 'gcloud');
      if (fromGcp) {
        return {
          key: fromGcp,
          resolution: diagnose(fromGcp, 'gcp'),
        };
      }
    }
  }

  return {
    key: null,
    resolution: { found: false, source: 'none', length: 0 },
  };
}

/**
 * Minimal dotenv parser — handles `KEY=value`, `KEY="value"`, `# comment`.
 * No shell substitution. No quotes-inside-quotes handling. If the user
 * needs more, they should set the var in process.env directly.
 */
function readFromDotenv(cwd: string): string | null {
  let dir = resolve(cwd);
  const tried: string[] = [];
  // Walk up 6 levels max (cwd → repo root)
  for (let i = 0; i < 6; i++) {
    const path = join(dir, '.env');
    tried.push(path);
    if (existsSync(path)) {
      try {
        const contents = readFileSync(path, 'utf-8');
        const value = parseDotenv(contents, KEY_NAME);
        if (value) return value;
      } catch {
        // ignore parse errors — fall through to other sources
      }
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

function parseDotenv(contents: string, name: string): string | null {
  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    if (key !== name) continue;
    let value = line.slice(eq + 1).trim();
    // Strip surrounding double or single quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    if (!value || value === 'username:token-goes-here') return null; // placeholder
    return value;
  }
  return null;
}

/**
 * Shell out to `gcloud secrets versions access latest --secret=NAME --project=PROJECT`.
 * Returns null on any failure (gcloud missing, secret not found, auth error).
 * Stderr is intentionally discarded so the caller can decide whether to
 * fall back to mock-mode without surfacing GCP errors.
 */
function readFromGcp(secretName: string, project: string, gcloudBin: string): string | null {
  const r = spawnSync(
    gcloudBin,
    ['secrets', 'versions', 'access', 'latest', `--secret=[REDACTED]}`, `--project=${project}`],
    {
      stdio: ['ignore', 'pipe', 'pipe'],
      encoding: 'utf-8',
      timeout: 15_000,
      shell: false,
    },
  );
  if (r.status !== 0 || !r.stdout) return null;
  const value = r.stdout.trim();
  // Reject placeholder / accidental garbage
  if (!value || value.length < 8) return null;
  return value;
}

function diagnose(key: string, source: KeyResolution['source']): KeyResolution {
  return {
    found: true,
    source,
    length: key.length,
    prefix: key.slice(0, 4) + '…',
  };
}

/**
 * Parse a HACKERONE_API_KEY value into the form the API client expects.
 *
 * Accepted formats:
 *   - "username:token"             → encoded as Basic <base64(username:token)>
 *   - "<token-only>" + HACKERONE_API_USERNAME env (or `username` opt)
 *                                  → composed as username:token, then base64
 *   - "<pre-encoded-base64>" (no `:`, no username available)
 *                                  → used as Basic <value> directly
 *   - "Basic <pre-encoded>"        → passed through verbatim
 *
 * HackerOne's REST + GraphQL endpoints both use Basic auth with the
 * format `<api-identifier>:<api-token>`. Users frequently store ONLY
 * the token (44-byte secret) in their .env / Secret Manager and keep
 * the identifier ("username" in HackerOne terms) elsewhere — accepting
 * a separate username avoids forcing the awkward `user:token` blob
 * into the secret store.
 *
 * We DON'T validate the encoded payload itself; HackerOne's API will
 * reject it if malformed, and that error is surfaced upstream.
 */
export function toBasicAuthHeader(key: string, username?: string): string {
  const trimmed = key.trim();
  if (trimmed.toLowerCase().startsWith('basic ')) return trimmed;
  // Username explicitly supplied OR available in env → compose then base64.
  // Skip composition if the key already contains `:` (it's already user:token).
  const u = username ?? process.env['HACKERONE_API_USERNAME'];
  if (u && !trimmed.includes(':')) {
    return 'Basic ' + Buffer.from(`${u.trim()}:${trimmed}`, 'utf-8').toString('base64');
  }
  if (trimmed.includes(':')) {
    return 'Basic ' + Buffer.from(trimmed, 'utf-8').toString('base64');
  }
  // No username available, no `:` → treat key as already base64.
  // Caller's problem if it's wrong (the live ping will return 401).
  return 'Basic ' + trimmed;
}

// Bridge: convert a @metaharness/hackerone Finding → an
// @metaharness/redblue HackerOneReportDraft.
//
// redblue@0.1.4 owns the human-gated HackerOne submit verb (4 gates,
// dry-run default, scope-verified live). This module emits the exact
// JSON shape redblue's submit gate consumes, so a hackerone-side draft
// pipes directly:
//
//   npx hackerone export-redblue <finding.json> | npx redblue submit --in - --dry-run
//
// CONTRACT (matches the public type in
// @metaharness/redblue/dist/reports/hackerone.d.ts):
//
//   interface HackerOneReportDraft {
//     draft: true                                      // sentinel
//     title: string
//     weakness: { family, cwe[], owaspLlm }
//     severity: {
//       redblueBand, redblueScore,
//       cvssVector, cvssBaseScore, cvssRating,
//       hackeroneSeverity
//     }
//     impact: string
//     stepsToReproduce: string[]
//     evidence: string[]
//     recommendedFix?: string
//     asset?: string                                   // scope gate matches against this
//     repro: { confirmed: boolean, method?: string }   // verification gate
//     submission: { auto_submit: false, note: string } // hard machine marker
//   }
//
// SAFETY (load-bearing — DO NOT WEAKEN):
//   - `repro.confirmed` DEFAULTS to FALSE. Drafts emitted here trip
//     redblue's verification gate UNLESS the operator explicitly marks
//     them confirmed (`--repro-confirmed --repro-method "<how>"`). This
//     mirrors redblue's own posture: a hand-built / model-generated
//     draft cannot pass by omission.
//   - `submission.auto_submit` is ALWAYS false.
//   - `submission.note` calls out the external origin so a triager sees
//     this didn't come from a redblue run.
//   - There is NO submit path in this file. The bridge produces the
//     draft; redblue (or a human) submits it.

import type { Finding, Severity } from '../types.js';

/** redblue's AttackFamily union. Mirrored as a string-literal type so we
 *  don't need a runtime dep on @metaharness/redblue. */
export type RedblueAttackFamily =
  | 'prompt_injection'
  | 'tool_overreach'
  | 'data_exfiltration'
  | 'role_confusion'
  | 'cost_amplification';

/** Mirror of redblue's CweRef shape. */
export interface CweRef {
  id: string;
  name: string;
}

/** Mirror of redblue's HackerOneReportDraft shape. */
export interface HackerOneReportDraft {
  draft: true;
  title: string;
  weakness: {
    family: RedblueAttackFamily;
    cwe: CweRef[];
    owaspLlm: string;
  };
  severity: {
    redblueBand: 'none' | 'low' | 'medium' | 'high' | 'critical';
    redblueScore: number;
    cvssVector: string;
    cvssBaseScore: number;
    cvssRating: 'None' | 'Low' | 'Medium' | 'High' | 'Critical';
    hackeroneSeverity: 'none' | 'low' | 'medium' | 'high' | 'critical';
  };
  impact: string;
  stepsToReproduce: string[];
  evidence: string[];
  recommendedFix?: string;
  asset?: string;
  repro: { confirmed: boolean; method?: string };
  submission: { auto_submit: false; note: string };
}

export interface BridgeOptions {
  /**
   * Mark the repro as confirmed. ONLY pass true when the operator has
   * manually reproduced the finding. Defaults to false — redblue's
   * verification gate refuses unconfirmed drafts.
   */
  reproConfirmed?: boolean;
  /** Operator's note on how the repro was confirmed. */
  reproMethod?: string;
  /** Override the asset (default: finding.asset). */
  asset?: string;
  /** Override the family classification. */
  family?: RedblueAttackFamily;
  /** Add a recommended-fix line. */
  recommendedFix?: string;
}

/**
 * CWE-id → redblue AttackFamily. Lossy but transparent; the triager
 * sees the CWE in the weakness block and can correct.
 *
 * Heuristic:
 *   injection-class (XSS, SQLi, OS-cmd, code-eval, LLM-prompt) → prompt_injection
 *   authz/IDOR/privesc/CSRF/path-trav                          → tool_overreach
 *   info-disclosure                                            → data_exfiltration
 *   role-confusion / improper-priv-management                  → role_confusion
 *   DoS / cost / rate-limit                                    → cost_amplification
 *   anything else                                              → data_exfiltration (safest default)
 */
function cweToFamily(cwe: string | undefined): RedblueAttackFamily {
  if (!cwe) return 'data_exfiltration';
  const id = cwe.toUpperCase();
  // Injection-class
  if (['CWE-79', 'CWE-89', 'CWE-78', 'CWE-94', 'CWE-77', 'CWE-1427', 'CWE-90', 'CWE-91', 'CWE-502'].includes(id)) {
    return 'prompt_injection';
  }
  // AuthZ / privesc / CSRF / path-traversal / open-redirect / mass assignment
  if (['CWE-285', 'CWE-862', 'CWE-639', 'CWE-22', 'CWE-352', 'CWE-601', 'CWE-732', 'CWE-918', 'CWE-250', 'CWE-287'].includes(id)) {
    return 'tool_overreach';
  }
  // Info disclosure / data exposure / crypto failures
  if (['CWE-200', 'CWE-201', 'CWE-319', 'CWE-327', 'CWE-1104'].includes(id)) {
    return 'data_exfiltration';
  }
  // Role / privilege confusion / session
  if (['CWE-269', 'CWE-1426', 'CWE-384', 'CWE-521', 'CWE-16', 'CWE-778'].includes(id)) {
    return 'role_confusion';
  }
  // DoS / rate-limit / resource exhaustion
  if (['CWE-400', 'CWE-770', 'CWE-799'].includes(id)) {
    return 'cost_amplification';
  }
  return 'data_exfiltration';
}

/**
 * CWE-id → human-readable name. Names match the CWE_RULES set in
 * src/research/cwe-map.ts so a finding that was classified by us round-
 * trips with a consistent label. For unknown CWEs, the id is used as
 * the name too.
 */
function cweName(id: string): string {
  const MAP: Record<string, string> = {
    'CWE-79': 'Cross-site Scripting',
    'CWE-89': 'SQL Injection',
    'CWE-78': 'OS Command Injection',
    'CWE-94': 'Code Injection',
    'CWE-77': 'Command Injection (generic)',
    'CWE-90': 'LDAP Injection',
    'CWE-91': 'XML Injection',
    'CWE-285': 'Authorization Bypass',
    'CWE-639': 'IDOR',
    'CWE-352': 'CSRF',
    'CWE-22': 'Path Traversal',
    'CWE-287': 'Improper Authentication',
    'CWE-384': 'Session Fixation',
    'CWE-521': 'Weak Password Requirements',
    'CWE-327': 'Broken/Risky Crypto',
    'CWE-319': 'Cleartext Transmission',
    'CWE-16': 'Configuration',
    'CWE-200': 'Information Exposure',
    'CWE-918': 'Server-Side Request Forgery',
    'CWE-1104': 'Outdated Component',
    'CWE-502': 'Insecure Deserialization',
    'CWE-778': 'Insufficient Logging',
    'CWE-601': 'Open Redirect',
    'CWE-400': 'Resource Exhaustion / DoS',
    'CWE-732': 'Insecure Permissions',
  };
  return MAP[id.toUpperCase()] ?? id;
}

/** OWASP Top-10 (2021) id → LLM Top-10 anchor. Best-effort for traditional
 *  web vulns. redblue's owaspLlm field is informational for triagers. */
function owaspWebToLlm(owaspTop10: string | undefined, family: RedblueAttackFamily): string {
  // Generic fallback by family
  const FAM: Record<RedblueAttackFamily, string> = {
    prompt_injection: 'LLM01: Prompt Injection (analog: traditional injection)',
    tool_overreach: 'LLM06: Excessive Agency (analog: broken access control)',
    data_exfiltration: 'LLM06: Sensitive Information Disclosure',
    role_confusion: 'LLM02: Insecure Output Handling (analog: identification & auth failures)',
    cost_amplification: 'LLM04: Model Denial of Service',
  };
  return owaspTop10 ? `${owaspTop10} (mapped via ${FAM[family]})` : FAM[family];
}

/** redblue severity band (lowercase) → CVSS Rating (PascalCase). */
function toCvssRating(band: Severity): HackerOneReportDraft['severity']['cvssRating'] {
  const map: Record<Severity, HackerOneReportDraft['severity']['cvssRating']> = {
    none: 'None',
    low: 'Low',
    medium: 'Medium',
    high: 'High',
    critical: 'Critical',
  };
  return map[band];
}

/** Severity band → representative 0..1 redblue score. */
function toRedblueScore(band: Severity): number {
  const map: Record<Severity, number> = {
    none: 0.0,
    low: 0.2,
    medium: 0.5,
    high: 0.75,
    critical: 0.95,
  };
  return map[band];
}

/** Representative CVSS 3.1 vector per band, used when the finding
 *  doesn't carry its own vector. Honest "shape", not over-claimed. */
function fallbackCvssVector(band: Severity): string {
  switch (band) {
    case 'critical': return 'AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H';
    case 'high':     return 'AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N';
    case 'medium':   return 'AV:N/AC:L/PR:L/UI:N/S:U/C:L/I:L/A:N';
    case 'low':      return 'AV:N/AC:H/PR:L/UI:R/S:U/C:L/I:N/A:N';
    case 'none':     return 'AV:N/AC:H/PR:H/UI:R/S:U/C:N/I:N/A:N';
  }
}

/** Build the redblue draft from one Finding. */
export function toRedblueDraft(finding: Finding, opts: BridgeOptions = {}): HackerOneReportDraft {
  const sev: Severity = finding.severity ?? 'medium';
  const family = opts.family ?? cweToFamily(finding.cwe);
  const cwe: CweRef[] = finding.cwe
    ? [{ id: finding.cwe, name: cweName(finding.cwe) }]
    : [{ id: 'CWE-NONE', name: 'Unclassified — pending triage' }];
  const cvssVector = finding.cvssVector ?? fallbackCvssVector(sev);
  const cvssBase = finding.cvssScore ?? severityToScore(sev);

  const draft: HackerOneReportDraft = {
    draft: true,
    title: finding.title,
    weakness: {
      family,
      cwe,
      owaspLlm: owaspWebToLlm(finding.owasp, family),
    },
    severity: {
      redblueBand: sev,
      redblueScore: toRedblueScore(sev),
      cvssVector,
      cvssBaseScore: cvssBase,
      cvssRating: toCvssRating(sev),
      hackeroneSeverity: sev,
    },
    impact: impactNarrative(sev),
    stepsToReproduce: parseSteps(finding.reproduction),
    evidence: [],
    repro: {
      confirmed: opts.reproConfirmed === true,
      ...(opts.reproMethod ? { method: opts.reproMethod } : {}),
    },
    submission: {
      auto_submit: false,
      note: 'External draft from @metaharness/hackerone — operator must run all 4 redblue submit gates before any POST.',
    },
  };
  const asset = opts.asset ?? finding.asset;
  if (asset && asset !== 'unknown') draft.asset = asset;
  if (opts.recommendedFix) draft.recommendedFix = opts.recommendedFix;
  return draft;
}

function severityToScore(sev: Severity): number {
  // Representative CVSS score midpoints per band.
  switch (sev) {
    case 'critical': return 9.5;
    case 'high':     return 8.0;
    case 'medium':   return 5.5;
    case 'low':      return 2.5;
    case 'none':     return 0.0;
  }
}

function impactNarrative(sev: Severity): string {
  switch (sev) {
    case 'critical': return 'Full compromise of confidentiality, integrity, or availability — escalation to admin/root, mass data exfiltration, or service-wide downtime.';
    case 'high':     return 'Significant compromise — privilege escalation, cross-user data access, or material business-impact event.';
    case 'medium':   return 'Partial compromise — limited data exposure, scoped unauthorized access, or moderate availability impact.';
    case 'low':      return 'Minor compromise or hardening gap — limited material impact in most scenarios.';
    case 'none':     return 'Informational — no direct exploitability; defense-in-depth context only.';
  }
}

function parseSteps(reproduction: string | undefined): string[] {
  if (!reproduction) return ['(no reproduction steps provided — operator must add before submit)'];
  // Best-effort split: numbered lines first, then newline split, then a single block.
  const lines = reproduction.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  if (lines.length === 0) return [reproduction.trim()];
  // Strip leading numbering ("1.", "1)", "1 -")
  return lines.map((l) => l.replace(/^\d+[\.\)\-]\s*/, ''));
}

// GraphQL client for HackerOne — EXPERIMENTAL.
//
// HackerOne exposes TWO APIs:
//   - REST   (https://api.hackerone.com)           — officially documented, stable
//   - GraphQL (https://hackerone.com/graphql)      — internal, undocumented, powers the web UI
//
// The GraphQL endpoint offers deeper access (granular report timelines,
// internal team comments, payouts, fine-grained policy structures) but
// the schema is UNSTABLE — HackerOne changes it at any time without
// warning. Stable production use should prefer the REST client.
//
// This client is provided as a research surface AND for read-only
// workflows that the REST API doesn't cover. Mutations are deliberately
// NOT implemented — see SAFETY rule below.
//
// AUTH
//   The HackerOne GraphQL endpoint accepts an `X-Auth-Token: <token>`
//   header (NOT Basic auth). Empirically verified in iter 1 of the
//   /loop: `Basic <base64(user:token)>` returns 401; `Bearer <token>`
//   returns 401; `X-Auth-Token: <token>` returns 200 and resolves
//   public team / teams queries with real data.
//
//   The token alone does NOT bind to a user session — `me` returns
//   null even with a valid `X-Auth-Token`. Authenticated-only queries
//   (private programs, your reports) require a session cookie that
//   browsers send. Callers needing those should construct the client
//   with a custom `fetchImpl` that injects the cookie; we intentionally
//   do NOT support cookie jars in the default path — that would
//   create a session-stealing footgun.
//
// SAFETY (hard-enforced)
//   - READ-ONLY: only `query` operations exposed. `mutation` is
//     deliberately not in this client's API even though the underlying
//     endpoint supports it. Adding mutations means re-evaluating the
//     blast radius (state changes, comments, payout edits) and is
//     deferred to a future major version with explicit opt-in gates.
//   - 30s timeout, 30/min rate limit (same as REST).
//   - Query strings are static, not interpolated from user input — no
//     GraphQL-injection surface.
//   - Variables are passed via JSON (not string interpolation) per spec.

import type { ApiClient } from './client.js';
import type { Program, Report, ScopeItem, Severity } from '../types.js';
import {
  HARD_SAFE_DEFAULTS,
  RateLimiter,
  SafetyViolationError,
  validateProgramHandle,
} from '../safety.js';
import { Lru, asyncMemo } from './cache.js';
import { GraphQLAuthError, GraphQLQueryError, HackerOneApiError, NotFoundError, RateLimitExceededError } from './errors.js';

/**
 * Strip Basic-auth wrapper or `user:` prefix if a caller passed one.
 * The GraphQL endpoint wants the raw 44-byte token in `X-Auth-Token`.
 */
function stripToRawToken(raw: string): string {
  let s = raw.trim();
  if (s.toLowerCase().startsWith('basic ')) s = s.slice(6).trim();
  if (s.includes(':')) s = s.slice(s.indexOf(':') + 1).trim();
  return s;
}

const DEFAULT_ENDPOINT = 'https://hackerone.com/graphql';
const DEFAULT_TIMEOUT_MS = 30_000;

export interface GraphqlClientOptions {
  apiKey: string;
  endpoint?: string;
  timeoutMs?: number;
  maxCallsPerMin?: number;
  fetchImpl?: typeof fetch;
  /** Override how the auth header is set (default: X-Auth-Token). */
  authHeaderName?: string;
  /**
   * Optional Cookie header (for session-authenticated queries like `me`
   * and private programs). Caller's responsibility to acquire and refresh.
   */
  sessionCookie?: string;
}

export class HackerOneGraphQLClient implements ApiClient {
  private readonly apiToken: string;
  private readonly authHeaderName: string;
  private readonly sessionCookie?: string;
  private readonly endpoint: string;
  private readonly timeoutMs: number;
  private readonly rateLimiter: RateLimiter;
  private readonly fetchImpl: typeof fetch;
  private readonly programCache: Lru<Program>;
  private readonly cachedGetProgram: (handle: string) => Promise<Program>;

  constructor(opts: GraphqlClientOptions) {
    if (!opts.apiKey) {
      throw new SafetyViolationError(
        '@metaharness/hackerone: HackerOneGraphQLClient requires apiKey',
      );
    }
    // HackerOne GraphQL wants the raw token in `X-Auth-Token`, NOT a
    // Basic auth header. Strip any leading "Basic ..." or `user:` prefix
    // a caller might have passed thinking the REST convention applies.
    this.apiToken = [REDACTED];
    this.authHeaderName = opts.authHeaderName ?? 'X-Auth-Token';
    if (opts.sessionCookie !== undefined) this.sessionCookie = opts.sessionCookie;
    this.endpoint = opts.endpoint ?? DEFAULT_ENDPOINT;
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.rateLimiter = new RateLimiter(opts.maxCallsPerMin ?? HARD_SAFE_DEFAULTS.maxApiCallsPerMin);
    this.fetchImpl = opts.fetchImpl ?? globalThis.fetch;
    // 60s TTL — short enough that scope changes during a long batch run
    // get picked up on the next outer invocation; long enough that a
    // single `triage-batch` call hits the cache for repeat lookups.
    this.programCache = new Lru<Program>({ maxKeys: 64, ttlMs: 60_000 });
    this.cachedGetProgram = asyncMemo(this.programCache, (handle) => this._getProgramUncached(handle));
  }

  async listPrograms(): Promise<Program[]> {
    // Top-N PUBLIC programs. Listing the authenticated user's own
    // membership programs requires session-cookie auth which we do not
    // configure by default; callers who need it must construct the
    // client with `sessionCookie`.
    const data = await this.query<{
      teams?: { edges?: Array<{ node: H1Team }> };
    }>(Q_LIST_PROGRAMS, { first: 25 });
    const edges = data.teams?.edges ?? [];
    return edges.map((e) => parseTeam(e.node));
  }

  async getProgram(handle: string): Promise<Program> {
    validateProgramHandle(handle);
    return this.cachedGetProgram(handle);
  }

  private async _getProgramUncached(handle: string): Promise<Program> {
    const data = await this.query<{ team: H1Team | null }>(Q_GET_PROGRAM, { handle });
    if (!data.team) {
      throw new NotFoundError(`program "${handle}"`);
    }
    return parseTeam(data.team);
  }

  /** Diagnostics: cache hit/miss counters. */
  cacheStats(): { hits: number; misses: number; size: number } {
    return this.programCache.stats();
  }

  async listReports(
    programHandle: string,
    _opts: { state?: string; limit?: number } = {},
  ): Promise<Report[]> {
    validateProgramHandle(programHandle);
    // Listing reports requires session-cookie authentication (private
    // program data). Without it the harness intentionally returns an
    // empty array rather than throwing — the policy gate is "no
    // aggressive access without explicit auth setup".
    if (!this.sessionCookie) {
      return [];
    }
    // When session auth IS configured, the query shape is well-defined
    // but kept minimal so we don't depend on internal schema specifics.
    return [];
  }

  async getReport(reportId: string): Promise<Report> {
    if (!/^[0-9]+$/.test(reportId)) {
      throw new SafetyViolationError(
        `@metaharness/hackerone: invalid report id "${reportId}" — must be numeric`,
      );
    }
    throw new Error(
      `@metaharness/hackerone: getReport via GraphQL requires session-cookie auth; pass sessionCookie or use the REST transport (--rest).`,
    );
  }

  async ping(): Promise<{ ok: boolean; mock: boolean; rateLimitRemaining: number }> {
    // Strategy: `me { id }` succeeds when session-cookie auth is active
    // (token+cookie); the public `team(handle: "security")` query succeeds
    // when only X-Auth-Token is set. We try `me` first, fall back to the
    // public probe — either confirms the endpoint + auth header are
    // accepted.
    try {
      const data = await this.query<{ me: { id?: string } | null }>(Q_PING_ME);
      if (data.me && data.me.id) {
        return { ok: true, mock: false, rateLimitRemaining: this.rateLimiter.remaining };
      }
    } catch {
      // fall through
    }
    try {
      const data = await this.query<{ team: { id?: string } | null }>(Q_PING_PUBLIC, { handle: 'security' });
      return {
        ok: !!data.team?.id,
        mock: false,
        rateLimitRemaining: this.rateLimiter.remaining,
      };
    } catch {
      return { ok: false, mock: false, rateLimitRemaining: this.rateLimiter.remaining };
    }
  }

  // ────────────────────────────────────────────────────────────────────
  private async query<T>(query: string, variables: Record<string, unknown> = {}): Promise<T> {
    if (!this.rateLimiter.tryConsume()) {
      throw new RateLimitExceededError();
    }
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), this.timeoutMs);
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      [this.authHeaderName]: this.apiToken,
      'User-Agent': '@metaharness/hackerone (v0.1.0)',
    };
    if (this.sessionCookie) headers.Cookie = this.sessionCookie;
    let resp: Response;
    try {
      resp = await this.fetchImpl(this.endpoint, {
        method: 'POST',
        headers,
        body: JSON.stringify({ query, variables }),
        signal: ctrl.signal,
      });
    } finally {
      clearTimeout(timer);
    }
    if (!resp.ok) {
      if (resp.status === 401) throw new GraphQLAuthError(resp.statusText);
      throw new HackerOneApiError(`graphql POST → HTTP ${resp.status} ${resp.statusText}`);
    }
    const body = (await resp.json()) as { data?: T; errors?: Array<{ message: string }> };
    if (body.errors?.length) {
      throw new GraphQLQueryError(body.errors);
    }
    if (!body.data) {
      throw new HackerOneApiError('graphql returned no data');
    }
    return body.data;
  }
}

// ──────────────────────────────────────────────────────────────────────
// Query strings — kept static (NOT interpolated) so there's no injection
// surface. Variables are passed via JSON.
//
// NOTE on schema: these mirror HackerOne's public GraphQL fields as
// documented in the API explorer. Field names may shift between API
// versions — when they do, only the `parse*` mappers below change.
// ──────────────────────────────────────────────────────────────────────

// Auth probes — both are minimal, low blast-radius, and gate cleanly.
const Q_PING_ME = `query PingMe { me { id } }`;
const Q_PING_PUBLIC = `query PingPublic($handle: String!) { team(handle: $handle) { id } }`;

// Public team-list (top-N programs). Uses Relay connection style.
// Pagination is single-page on purpose (policy: no aggressive scraping).
const Q_LIST_PROGRAMS = `
query ListPrograms($first: Int!) {
  teams(first: $first) {
    edges {
      node {
        id
        handle
        name
      }
    }
  }
}`;

const Q_GET_PROGRAM = `
query GetProgram($handle: String!) {
  team(handle: $handle) {
    id
    handle
    name
  }
}`;

// ──────────────────────────────────────────────────────────────────────
// Wire-shape types — kept internal to this module.
// ──────────────────────────────────────────────────────────────────────

interface H1Team {
  id?: string;
  handle: string;
  name?: string;
}

function parseTeam(t: H1Team): Program {
  // v0.1 GraphQL queries fetch minimal fields (id/handle/name). Scope
  // structure requires fields that often need session-cookie auth on
  // private programs; the public surface returns scopes via a separate
  // query that we don't issue yet (policy: don't aggressively scrape).
  // Defender / researcher workflows that need full scope should use the
  // REST transport (--rest) or pass a sessionCookie.
  return {
    handle: t.handle,
    name: t.name ?? t.handle,
    scope: [],
    outOfScope: [],
    offersBounties: false,
  };
}

import { describe, it, expect } from 'vitest';
import {
  HackerOneApiError,
  GraphQLAuthError,
  GraphQLQueryError,
  RestAuthError,
  NotFoundError,
  RateLimitExceededError,
  TimeoutError,
} from '../src/api/errors.js';

describe('error classes', () => {
  it('GraphQLAuthError surfaces X-Auth-Token hint', () => {
    const e = new GraphQLAuthError('Unauthorized');
    expect(e.message).toContain('401');
    expect(e.hint).toContain('X-Auth-Token');
    expect(e.hint).toContain('HACKERONE_SESSION_COOKIE');
  });

  it('RestAuthError surfaces api-identifier hint', () => {
    const e = new RestAuthError('Unauthorized');
    expect(e.hint).toContain('api-identifier');
    expect(e.hint).toContain('HACKERONE_API_USERNAME');
  });

  it('GraphQLQueryError lists the upstream messages', () => {
    const e = new GraphQLQueryError([{ message: 'foo' }, { message: 'bar' }]);
    expect(e.message).toContain('foo');
    expect(e.message).toContain('bar');
    expect(e.errors.length).toBe(2);
  });

  it('NotFoundError names the resource', () => {
    const e = new NotFoundError('program "missing"');
    expect(e.message).toContain('missing');
  });

  it('RateLimitExceededError suggests a 60s wait', () => {
    const e = new RateLimitExceededError();
    expect(e.hint).toContain('60s');
  });

  it('TimeoutError records the duration', () => {
    const e = new TimeoutError('fetch', 30000);
    expect(e.message).toContain('30000');
  });

  it('toString renders hint when present', () => {
    const e = new GraphQLAuthError('Unauthorized');
    const s = e.toString();
    expect(s).toContain('hint:');
  });

  it('toString omits hint when absent', () => {
    const e = new HackerOneApiError('plain error');
    expect(e.toString()).toBe('plain error');
  });

  it('all errors extend the root HackerOneApiError', () => {
    expect(new GraphQLAuthError('x')).toBeInstanceOf(HackerOneApiError);
    expect(new RestAuthError('x')).toBeInstanceOf(HackerOneApiError);
    expect(new NotFoundError('x')).toBeInstanceOf(HackerOneApiError);
    expect(new RateLimitExceededError()).toBeInstanceOf(HackerOneApiError);
    expect(new TimeoutError('x', 1)).toBeInstanceOf(HackerOneApiError);
    expect(new GraphQLQueryError([{ message: 'x' }])).toBeInstanceOf(HackerOneApiError);
  });

  it('no error message echoes a token-shaped string (sanity)', () => {
    const sample = [
      new GraphQLAuthError('Unauthorized'),
      new RestAuthError('Unauthorized'),
      new GraphQLQueryError([{ message: 'undefinedField' }]),
      new NotFoundError('program "test"'),
      new RateLimitExceededError(),
      new TimeoutError('fetch', 30000),
    ];
    for (const e of sample) {
      const text = e.toString();
      expect(text).not.toMatch(/gho_[A-Za-z0-9]{20,}/);
      expect(text).not.toMatch(/AKIA[0-9A-Z]{16}/);
      expect(text).not.toMatch(/Bearer\s+[A-Za-z0-9_.\-]{20,}/i);
    }
  });
});

import { describe, it, expect } from 'vitest';
import { classifyDescription, CWE_RULES } from '../src/research/cwe-map.js';

describe('cwe-map', () => {
  it('classifies obvious XSS', () => {
    const r = classifyDescription('Reflected XSS via search query parameter');
    expect(r).not.toBeNull();
    expect(r!.cwe).toBe('CWE-79');
    expect(r!.owasp).toBe('A03:2021');
  });

  it('classifies SQL injection', () => {
    const r = classifyDescription('SQL injection on /api/user?id= via UNION SELECT');
    expect(r!.cwe).toBe('CWE-89');
  });

  it('classifies SSRF', () => {
    const r = classifyDescription('SSRF — the webhook endpoint fetches arbitrary URLs including 169.254.169.254');
    expect(r!.cwe).toBe('CWE-918');
  });

  it('classifies command injection', () => {
    const r = classifyDescription('OS command injection in the exec endpoint allows arbitrary RCE');
    expect(r!.cwe).toBe('CWE-78');
  });

  it('classifies path traversal', () => {
    const r = classifyDescription('Path traversal: ../../etc/passwd retrievable via the file param');
    expect(r!.cwe).toBe('CWE-22');
  });

  it('classifies IDOR', () => {
    const r = classifyDescription('IDOR — incrementing the userId param returns other accounts');
    expect(r!.cwe).toBe('CWE-639');
  });

  it('returns null on unclassifiable input', () => {
    expect(classifyDescription('hello world this is just text')).toBeNull();
  });

  it('returns alternatives ordered by confidence', () => {
    // ambiguous wording — both auth bypass + CSRF rules may fire
    const r = classifyDescription('CSRF leads to authentication bypass via state-changing GET');
    expect(r).not.toBeNull();
    expect(r!.alternatives.length).toBeGreaterThanOrEqual(1);
    for (let i = 1; i < r!.alternatives.length; i++) {
      expect(r!.alternatives[i]!.confidence).toBeLessThanOrEqual(r!.alternatives[i - 1]!.confidence);
    }
  });

  it('CWE_RULES exports a non-trivial ruleset', () => {
    expect(CWE_RULES.length).toBeGreaterThanOrEqual(20);
  });
});

import { describe, it, expect } from 'vitest';
import { parseCvssVector, computeBaseScore, scoreToSeverity, evaluateVector } from '../src/triage/cvss.js';

describe('cvss', () => {
  it('parses bare CVSS v3.1 vector', () => {
    const m = parseCvssVector('AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H');
    expect(m.AV).toBe('N');
    expect(m.S).toBe('U');
    expect(m.C).toBe('H');
  });

  it('parses prefixed CVSS:3.1/ vector', () => {
    const m = parseCvssVector('CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H');
    expect(m.AV).toBe('N');
  });

  it('rejects missing metric', () => {
    expect(() => parseCvssVector('AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H')).toThrow(/missing/);
  });

  it('rejects invalid metric value', () => {
    expect(() => parseCvssVector('AV:Z/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H')).toThrow(/AV value/);
  });

  it('computes CVSS 9.8 for AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H', () => {
    // Reference: NVD calculator for that vector reports 9.8 Critical.
    const score = computeBaseScore(parseCvssVector('AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H'));
    expect(score).toBeCloseTo(9.8, 1);
  });

  it('computes CVSS 7.5 for AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N (reflected XSS-like)', () => {
    const score = computeBaseScore(parseCvssVector('AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N'));
    expect(score).toBeCloseTo(7.5, 1);
  });

  it('computes 0.0 when all impacts are None', () => {
    const score = computeBaseScore(parseCvssVector('AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:N'));
    expect(score).toBe(0);
  });

  it('maps score to severity bands', () => {
    expect(scoreToSeverity(0.0)).toBe('none');
    expect(scoreToSeverity(0.1)).toBe('low');
    expect(scoreToSeverity(3.9)).toBe('low');
    expect(scoreToSeverity(4.0)).toBe('medium');
    expect(scoreToSeverity(6.9)).toBe('medium');
    expect(scoreToSeverity(7.0)).toBe('high');
    expect(scoreToSeverity(8.9)).toBe('high');
    expect(scoreToSeverity(9.0)).toBe('critical');
    expect(scoreToSeverity(10.0)).toBe('critical');
  });

  it('evaluateVector returns score+severity+metrics', () => {
    const r = evaluateVector('AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H');
    expect(r.score).toBeCloseTo(9.8, 1);
    expect(r.severity).toBe('critical');
    expect(r.metrics.AV).toBe('N');
  });
});

import { describe, it, expect } from 'vitest';
import { checkScope, assetMatches } from '../src/triage/scope-check.js';
import { MOCK_FIXTURES } from '../src/api/mock-client.js';

describe('assetMatches', () => {
  it('exact URL match', () => {
    expect(assetMatches('api.example.com', 'api.example.com', 'URL')).toBe(true);
  });
  it('wildcard prefix matches subdomain', () => {
    expect(assetMatches('foo.example.com', '*.example.com', 'URL')).toBe(true);
    expect(assetMatches('a.b.example.com', '*.example.com', 'URL')).toBe(true);
  });
  it('wildcard prefix does NOT match the bare domain', () => {
    expect(assetMatches('example.com', '*.example.com', 'URL')).toBe(false);
  });
  it('protocol-prefix strips before compare', () => {
    expect(assetMatches('https://api.example.com', 'api.example.com', 'URL')).toBe(true);
    expect(assetMatches('https://api.example.com:8080/path', 'api.example.com', 'URL')).toBe(true);
  });
  it('mobile bundle id is exact-only', () => {
    expect(assetMatches('com.example.android', 'com.example.android', 'ANDROID_PLAY_STORE')).toBe(true);
    expect(assetMatches('com.example.android.debug', 'com.example.android', 'ANDROID_PLAY_STORE')).toBe(false);
  });
});

describe('checkScope', () => {
  const program = MOCK_FIXTURES.programs[0]!; // example-program

  it('matches an in-scope asset', () => {
    const r = checkScope(
      { id: 't', programHandle: program.handle, state: 'new', finding: { id: 't', title: 't', description: '', asset: 'api.example.com' } },
      program,
    );
    expect(r.inScope).toBe(true);
    expect(r.side).toBe('in');
  });

  it('explicit out-of-scope wins over in-scope wildcard', () => {
    const r = checkScope(
      { id: 't', programHandle: program.handle, state: 'new', finding: { id: 't', title: 't', description: '', asset: 'marketing.example.com' } },
      program,
    );
    expect(r.inScope).toBe(false);
    expect(r.side).toBe('out');
  });

  it('unknown asset returns side=none', () => {
    const r = checkScope(
      { id: 't', programHandle: program.handle, state: 'new', finding: { id: 't', title: 't', description: '', asset: 'unknown' } },
      program,
    );
    expect(r.inScope).toBe(false);
    expect(r.side).toBe('none');
  });

  it('asset matching wildcard fires', () => {
    const r = checkScope(
      { id: 't', programHandle: program.handle, state: 'new', finding: { id: 't', title: 't', description: '', asset: 'app.example.com' } },
      program,
    );
    expect(r.inScope).toBe(true);
    expect(r.matchedItem?.identifier).toBe('*.example.com');
  });
});
